create temporary table author_story_before on commit drop as select id,md5(coalesce(catastrophe_description,'')||coalesce(host_notes,'')) fingerprint from public.scenarios where id='SC08';
alter table public.scenarios add column combo_enabled boolean not null default true;
grant select(combo_enabled) on public.scenarios to authenticated;
update public.scenarios set combo_enabled=false where id='SC08';
create function alive_private.scenario_combos_enabled(p_scenario text) returns boolean
language sql stable security definer set search_path='' as $$select p_scenario<>'SC08' and coalesce((select combo_enabled from public.scenarios where id=p_scenario),false)$$;
revoke all on function alive_private.scenario_combos_enabled(text) from public,anon,authenticated;
-- Preserve all historical definitions, cards and manifests. The feature gate below
-- excludes the author's scenario without deleting or deactivating any data.
update public.scenarios set catastrophe_description='После обмена ядерными ударами небо затянуло пеплом. На поверхности — мороз, радиоактивная пыль и разрушенное сельское хозяйство. Ближайшие 5–10 лет нельзя рассчитывать на безопасную жизнь снаружи. Ваш шанс — подземное убежище, которое предстоит превратить в устойчивую систему, а не просто переждать в нём несколько недель.

Базовый реактор рассчитан на долгую работу, воздухоочистка установлена. Но наличие оборудования не означает, что оно обходится без ремонта, расходников и грамотного распределения энергии. Запасы продовольствия конечны. Группе нужны обслуживание убежища, воспроизводимая пища, контроль загрязнения и порядок обращения с водой и припасами. Внешние вылазки не являются обязательным источником деталей: опасность поверхности нельзя забыть ради удобного аргумента.

В случайной партии две выбранные связки обозначают главные задачи именно этого убежища. Полный комплект навыка, средства и знания открывает соответствующий план — например, обслуживание воздуха или запуск подземного урожая. Он не даёт бесконечной энергии и мгновенного урожая. Выбирайте людей, которые смогут действовать вместе, и объясняйте, как группа доживёт до результата, используя показанные запасы.',host_notes='Цель — обосновать устойчивое убежище на длительный срок. Реактор на 20 лет уже является базовым свойством: не требуйте ещё один генератор как скрытую обязательную карту. Ремонтный или резервный энергетический план нужен для надёжности и обслуживания. Учитывайте время до первого урожая, расход воды и чистоту зон. Выбранные две связки — основные проверяемые задачи раздачи; остальные вопросы решаются базовыми системами, раскрытыми картами и аргументированным планом. Не объявляйте поражение из-за отсутствия уникального предмета, которого не было в раздаче.

Правило честной раздачи: две выбранные связки задают основные трудности случайной партии. Остальные этапы не требуют третьей уникальной невыданной карты. Полный комплект должен быть доступен живым участникам и использоваться с соблюдением своих ограничений. Числовые запасы и изменения ведущего учитываются явно; творческий альтернативный план можно записать при вердикте.' where id='SC01' and id<>'SC08';
update public.scenarios set catastrophe_description='Океан поглотил большую часть суши. Над водой остались редкие возвышенности; погода стала влажной и непредсказуемой, а пресная вода — одним из самых ценных запасов. Вы укрылись в плавучем герметичном модуле со штатной опреснительной установкой. Это не беззащитная шлюпка, но и не вечный непотопляемый дом.

Впереди может быть долгий переход к подтверждённой пригодной земле. Корпус требует осмотров, опреснитель — энергии и ухода, сети — ремонта, а улов и дождевая вода не появляются по расписанию. Сообщения о суше необходимо проверять; выходить в море только потому, что на карте проведена линия, опасно.

Две связки случайной партии выделяют её главные задачи: например, поддерживать опреснение, укрепить платформу, выбрать курс или наладить промысел. Существующая установка не заменяет умеющего обслуживать её человека. Полная связка даёт рабочий способ решить названную задачу с указанными ограничениями. Обоснуйте маршрут, запасы и резерв на шторм, не обещая мгновенно осушить океан или гарантированный улов.',host_notes='Герметичный модуль и опреснитель уже присутствуют в базовых свойствах. Связка опреснения означает обслуживание штатной установки, а не получение воды из ничего. Цель — убедительный автономный переход и сохранение группы; длительность маршрута соотносите с показанными запасами. Рыбалка и дождевой сбор вероятностны. Не требуйте одновременно все шесть связок каталога: обязательные задачи конкретной случайной партии — две реально выбранные.

Правило честной раздачи: две выбранные связки задают основные трудности случайной партии. Остальные этапы не требуют третьей уникальной невыданной карты. Полный комплект должен быть доступен живым участникам и использоваться с соблюдением своих ограничений. Числовые запасы и изменения ведущего учитываются явно; творческий альтернативный план можно записать при вердикте.' where id='SC02' and id<>'SC08';
update public.scenarios set catastrophe_description='Космическая аномалия изменила человеческое сознание. Появились телепатия, иллюзии и опасные зоны, где восприятие больше нельзя считать надёжным. Многие люди утратили контроль, а псионические штормы способны за короткое время разрушить личность. Они особенно часто возникают возле крупных городов, но удалённость сама по себе не гарантирует безопасности.

Ваше убежище располагает пси-экранированными комнатами и автономным питанием. Экран — ограниченная техническая защита, а не абсолютная неуязвимость. Нужны обслуживание, наблюдение и согласованные действия группы. Люди должны уметь отличать тревожные признаки от ложной тревоги, помогать друг другу при потере ориентации и вовремя отказываться от опасного выхода.

В случайной партии две выбранные связки могут дать план ментальной защиты, раннего предупреждения, устойчивой комнаты, взаимной проверки, обходного маршрута или помощи при кризисе. Ни один план не требует, чтобы обычный человек внезапно получил сверхспособности. Подбирайте сочетания карт и объясняйте границы защиты, расход питания и резервное действие при её отказе.',host_notes='Все специальные пси-приборы и эффекты являются условностями игрового мира и действуют только в границах текста карты. Базовое экранирование уже есть. Не превращайте его ни в бесполезную декорацию, ни в абсолютный щит. Полный комплект связки даёт описанный ограниченный план; не требуйте дополнительной скрытой пси-профессии. Психологическая помощь не является магическим лечением.

Правило честной раздачи: две выбранные связки задают основные трудности случайной партии. Остальные этапы не требуют третьей уникальной невыданной карты. Полный комплект должен быть доступен живым участникам и использоваться с соблюдением своих ограничений. Числовые запасы и изменения ведущего учитываются явно; творческий альтернативный план можно записать при вердикте.' where id='SC03' and id<>'SC08';
update public.scenarios set catastrophe_description='Мир сковало оледенение. На поверхности мороз достигает −60°C, привычные маршруты исчезли под снегом и льдом. Жизнь снаружи без специальной подготовки крайне опасна. Уцелевшие сооружают подземные убежища и купола, но доступ к каждому из них ещё нужно подтвердить.

У вашей группы уже есть геотермальное отопление и усиленная теплоизоляция. Главный вопрос — как поддерживать их работу: насосы ломаются, стыки промерзают, герметичный воздушный контур требует проверки. Источник тепла не делает воду и еду бесконечными, а утеплённая одежда не позволяет бесконечно находиться снаружи.

Две выбранные связки задают приоритеты случайной партии: обслуживание тепла, устранение утечек, дыхательный контур, вода из льда, небольшая тёплая теплица или подготовленный переход. Если в раздаче выбран переход, он требует снаряжения, проверенного маршрута и условий для отмены. Если он не выбран, выход к куполу не становится скрытым обязательным условием победы: можно обосновать жизнь в исходном убежище.',host_notes='Базовый геотермальный источник и изоляция исправны на старте, но требуют эксплуатации. Не требуйте заново добыть источник, уже указанный в свойствах. Свет, пищу, воздух и воду учитывайте по показанным ресурсам и картам. Нельзя объявлять внезапное обязательное путешествие к куполу, если партия строила автономное убежище. Выбранные связки открывают ограниченные планы, а не отменяют климат.

Правило честной раздачи: две выбранные связки задают основные трудности случайной партии. Остальные этапы не требуют третьей уникальной невыданной карты. Полный комплект должен быть доступен живым участникам и использоваться с соблюдением своих ограничений. Числовые запасы и изменения ведущего учитываются явно; творческий альтернативный план можно записать при вердикте.' where id='SC04' and id<>'SC08';
update public.scenarios set catastrophe_description='Круизный лайнер затонул во время шторма. Ваша группа оказалась в спасательной лодке с прочным герметичным корпусом и системой дождевого сбора. Корпус удерживает лодку на воде, но один из стыков повреждён и требует временного ремонта. До известного острова около суток при правильном курсе; погода и снос могут увеличить переход.

Исходного запаса пресной воды хватает примерно на три дня при обычном расходе. Еды мало, дождь не гарантирован, а сигнал бедствия ещё не передан. Самостоятельно плыть до берега слишком опасно. Остров даёт возможность укрыться, но незнакомые растения и животные не становятся безопасными только потому, что группа голодна.

В случайной партии две связки выделяют основные задачи: удержать лодку, передать сигнал, проложить курс, найти безопасную пищу, сохранить воду или помочь пострадавшим. Сигнализация и навигация не объявляются одновременно безвозвратно уничтоженными: подходящий комплект действительно может восстановить или заменить их. Сохраните нужных людей и предметы, объясните порядок действий и запас на неудачный день.',host_notes='Различайте прочность основного корпуса и локальную течь: ремонтная связка имеет смысл, не превращая лодку в заведомо обречённую. Вода на три дня — сюжетный исходный запас, расход согласуйте до оценки финала. Переданный сигнал не означает мгновенное прибытие спасателей. Путь к острову и ожидание спасения могут быть разными обоснованными планами. Не требуйте неизвестный редкий предмет сверх выбранных комплектов.

Правило честной раздачи: две выбранные связки задают основные трудности случайной партии. Остальные этапы не требуют третьей уникальной невыданной карты. Полный комплект должен быть доступен живым участникам и использоваться с соблюдением своих ограничений. Числовые запасы и изменения ведущего учитываются явно; творческий альтернативный план можно записать при вердикте.' where id='SC05' and id<>'SC08';
update public.scenarios set catastrophe_description='Новая инфекция разрушила города. Заражённые агрессивны, собираются в орды и особенно опасны ночью. Контакт с кровью и укусы представляют угрозу; в этом игровом мире опасность может существовать и в воздухе. Знаний о болезни недостаточно, чтобы считать кого-либо неуязвимым.

Вы нашли укрытие с баррикадированными входами и установленной автоматической фильтрацией. Это реальная стартовая защита, которую нужно обслуживать. Электросети и обычное снабжение не работают. Нужны чистые зоны, контроль контактов, вода, ограниченное питание оборудования и безопасный способ пополнять запасы. Ночные вылазки не являются допустимым стандартным решением.

Две выбранные связки определяют основные задачи партии: вентиляционная изоляция, укрепление, тихое питание, карантин, дневное снабжение или безопасная вода. Полный комплект позволяет организовать описанный процесс, но не создаёт вакцину и не гарантирует, что заражение невозможно. Обсуждайте раскрытые симптомы и ограничения без произвольных скрытых укусов, добавленных после выбора состава.',host_notes='Базовые баррикады и фильтрация существуют и дают время на выбранные планы. Предупреждение о воздушной передаче не означает автоматическое заражение всех в любом помещении: оцените разделение зон и обслуживание фильтра. Фильтр или кипячение сами по себе не объявляются универсальным лечением. Не добавляйте задним числом обязательную вакцину, которой не было в раздаче. Выбранные связки и явно раскрытые угрозы определяют проверку; запасной план допустим при понятной цене.

Правило честной раздачи: две выбранные связки задают основные трудности случайной партии. Остальные этапы не требуют третьей уникальной невыданной карты. Полный комплект должен быть доступен живым участникам и использоваться с соблюдением своих ограничений. Числовые запасы и изменения ведущего учитываются явно; творческий альтернативный план можно записать при вердикте.' where id='SC06' and id<>'SC08';
update public.scenarios set catastrophe_description='Плотный туман почти поглотил дневной свет. Даже мощный прожектор даёт ограниченную видимость; короткое светлое окно помогает различать лишь часть местности. Существа в тумане охотятся на звук, а длительное вдыхание тумана вызывает спутанность восприятия и потерю памяти.

У убежища есть прожекторы и внутренняя навигация. Они полезны внутри и рядом со входом, но не освещают весь мир и не заменяют обратный путь при выходе. Уцелели отдельные пищевые культуры. Ограниченные вылазки возможны при тихом движении, проверенных ориентирах и понятном условии возвращения.

Две связки партии предлагают планы возвращения по тактильной линии, чистого воздуха, тихой разведки, беззвучного периметра, выращивания уцелевших культур или взаимной проверки восприятия. Не путайте бесшумный датчик с громкой сиреной: предупреждение должно помогать группе, а не звать хищников. Полный комплект даёт ограниченную возможность действовать, сохраняя опасность тумана.',host_notes='Внутренняя навигация и внешнее ориентирование — разные задачи. Прожекторы не отменяют короткую видимость. Не требуйте гарантированно работающий GPS, если выбран механический или тактильный путь. Срабатывание периметра должно оставаться тихим. Для пищи используются только известные уцелевшие культуры; обычная теплица не производит урожай мгновенно. Не вводите третью обязательную редкую способность сверх двух выбранных планов.

Правило честной раздачи: две выбранные связки задают основные трудности случайной партии. Остальные этапы не требуют третьей уникальной невыданной карты. Полный комплект должен быть доступен живым участникам и использоваться с соблюдением своих ограничений. Числовые запасы и изменения ведущего учитываются явно; творческий альтернативный план можно записать при вердикте.' where id='SC07' and id<>'SC08';
update public.scenarios set catastrophe_description='Большая часть суши исчезла под водой. Ваша группа живёт на плавучей платформе-бункере с дождевым и конденсатным сбором, резервным дизель-генератором и корпусом, рассчитанным на сильные, но не любые штормы. Топливо ограничено. Для долгой автономии одних начальных запасов недостаточно.

Необходимо поддерживать корпус, получать безопасную воду и пищу, защищать оборудование от сырости и проверять сведения о пригодной суше. Малую установку обработки воды можно собрать или восстановить при наличии соответствующего комплекта; исходный дождевой сбор не равен бесконечному опреснению. Морская лихорадка — возможная отдельная угроза, если она явно введена картами или условиями партии.

В случайном режиме две выбранные связки дают конкретные планы: опреснение, корпус, наблюдение за лихорадкой, промысел, сухие зоны или навигация. Профилактический набор не называется гарантированным лекарством. Для режима готовых персонажей действуют отдельные авторские заметки об их именах, предметах и взаимодействиях; их нельзя автоматически переносить на случайную раздачу, где таких персонажей нет.',host_notes='В случайной партии не требуйте названных по имени готовых персонажей и их уникальные предметы. Применяйте две выбранные связки и показанные угрозы. Дождевой/конденсатный сбор существует на старте; опреснение — отдельный план, которому нужны компоненты и питание. Базовый корпус выдерживает указанную для него нагрузку, но требует ухода. Лихорадка не появляется задним числом только потому, что не выбран эпидемиолог. В режиме preset используйте сохранённые ниже исходные заметки для готовых персонажей.

Правило честной раздачи: две выбранные связки задают основные трудности случайной партии. Остальные этапы не требуют третьей уникальной невыданной карты. Полный комплект должен быть доступен живым участникам и использоваться с соблюдением своих ограничений. Числовые запасы и изменения ведущего учитываются явно; творческий альтернативный план можно записать при вердикте.'||case when host_notes is null then '' else E'\n\nИсходные заметки ТОЛЬКО для готовых персонажей (preset):\n'||host_notes end where id='water_world' and id<>'SC08';
update public.scenarios set catastrophe_description='Янтарный Король давно принимает вас в замке за необычные умения и добрые дела. Сегодня он не притронулся к кубку: из Чёрных болот идёт облако Чумной Королевы. Через три рассвета оно достигнет стен, и камень не спасёт королевство.

У старой часовни можно ослабить чары и разомкнуть цепь, связывающую Королеву с её колоколом. Отряду предстоит добраться туда, защитить работу и вернуться с вестью. В лёгкой повозке есть места только для выбранной группы; остальные помогают готовить замок к эвакуации. Королевское снаряжение обеспечивает базовую возможность похода, а не заменяет все человеческие умения.

Базово повозка несёт восемь литров чистой воды. Для обычного двухдневного пути король выделяет дополнительные бурдюки по согласованному числу мест: ориентир — четыре литра на участника. Фактический исходный объём показан в ресурсах. Запас не бесконечен: задержка, потеря бурдюка или дополнительный расход потребуют пополнения. Водная связка нужна именно для такого резерва, а не чтобы дважды выдать уже имеющуюся воду. Кипячение не снимает магическое проклятие.

Две выбранные связки выделяют наиболее трудные задачи этой партии: помощь раненым, работа с цепью, защита обряда, резервная вода, обход болот или ослабление чар. Остальные этапы можно обосновать стартовыми артефактами и раскрытыми умениями; обязательного скрытого списка профессий нет. Магия не побеждает Королеву автоматически. Объясните порядок действий, ограничения и кто прикроет спутников, пока они работают.',host_notes='Три рассвета — сюжетный срок; число раундов задаётся настройками. Выбывшие остаются в замке. При новой раздаче базовая вода равна максимуму из 8 л и 4 л на планируемого участника в пределах числа игроков. Уже вручную изменённый ресурс не пополняется автоматически. План воды даёт резерв на задержку или потерю запаса; его угроза не противоречит обеспеченному обычному пути. Две выбранные связки — основные трудности, остальное обосновывается доступным снаряжением и аргументами. Если не выбраны кузнец или обряд, не требуйте единственную невыданную карту для цепи: допустите стартовый артефакт и объяснённый совместный способ. Полные связки делают планы доступными, но ведущий ещё проверяет защиту работающих, срок, расход и ограничения.

Правило честной раздачи: две выбранные связки задают основные трудности случайной партии. Остальные этапы не требуют третьей уникальной невыданной карты. Полный комплект должен быть доступен живым участникам и использоваться с соблюдением своих ограничений. Числовые запасы и изменения ведущего учитываются явно; творческий альтернативный план можно записать при вердикте.' where id='MEDIEVAL_PLAGUE_QUEEN' and id<>'SC08';

update public.bunker_properties set text='Королевская дорожная повозка. Лёгкая повозка с мулом, тентом и опечатанными бурдюками. Базовый запас — 8 литров чистой воды; к новой раздаче король добавляет воду по согласованному числу мест, из расчёта 4 литра на человека. Фактический запас показан в ресурсах. На болоте повозку придётся вести вручную.' where scenario_id='MEDIEVAL_PLAGUE_QUEEN' and type='base';
update alive_private.scenario_routes set threat='Задержка или потеря бурдюка истощает походный запас',outcome='Подготовлено пополнение воды на случай задержки или потери части запаса' where key='MEDIEVAL_PLAGUE_QUEEN_route_4';
do $$declare def text;begin
 def:=pg_get_functiondef('alive_private.seed_combos(text)'::regprocedure);
 def:=replace(def,'if r.card_mode=''preset'' then return;end if;','if r.card_mode=''preset'' or not alive_private.scenario_combos_enabled(r.scenario_id) then return;end if;');
 def:=replace(def,'for g in 1..2 loop',$patch$
 if r.scenario_id='MEDIEVAL_PLAGUE_QUEEN' then
  insert into public.room_resources(room_code,key,label,amount,unit)
  values(p_code,'water_liters','Чистая вода отряда',greatest(8,4*least(coalesce((r.settings->>'target_survivors')::int,1),(select count(*)::int from public.players where room_code=p_code and id<>r.host_id))),'л') on conflict(room_code,key) do nothing;
 end if;
 for g in 1..2 loop$patch$);execute def;
 def:=pg_get_functiondef('alive_private.draw(text,text,boolean)'::regprocedure);
 def:=replace(def,'where p.is_active and p.category=p_category','where p.is_active and p.category=p_category and (alive_private.scenario_combos_enabled(selected_scenario) or (coalesce(p.content_key,'''') not like ''combo_v1:%'' and coalesce(p.content_key,'''') not like ''scenario_route_v2:%''))');execute def;
 def:=pg_get_functiondef('alive_private.alive_combo_status(text)'::regprocedure);
 def:=replace(def,'full_access:=alive_private.host(p_code);','if not alive_private.scenario_combos_enabled((select scenario_id from public.rooms where code=p_code)) then return ''[]''::jsonb;end if;full_access:=alive_private.host(p_code);');execute def;
 def:=pg_get_functiondef('alive_private.scenario_route_catalog(text)'::regprocedure);
 def:=replace(def,'return (select','if not alive_private.scenario_combos_enabled(p_scenario) then return ''[]''::jsonb;end if;return (select');execute def;
 def:=pg_get_functiondef('alive_private.combo_verdict_guard()'::regprocedure);
 def:=replace(def,'new.card_mode<>''preset'' then','new.card_mode<>''preset'' and alive_private.scenario_combos_enabled(new.scenario_id) then');execute def;
 def:=pg_get_functiondef('alive_private.generate(text)'::regprocedure);
 def:=replace(def,quote_literal('Карты розданы. В случайной колоде подготовлены два пути выживания из трёх компонентов; карточки сбалансированы.'),$message$case when r.card_mode<>'preset' and alive_private.scenario_combos_enabled(r.scenario_id) then 'Карты розданы. В случайной колоде подготовлены два пути выживания из трёх компонентов; карточки сбалансированы.' else 'Карты розданы по условиям сценария; новые связки не применяются.' end$message$);execute def;
end $$;
do $$begin
 if exists(select 1 from author_story_before b join public.scenarios s using(id) where b.fingerprint<>md5(coalesce(s.catastrophe_description,'')||coalesce(s.host_notes,''))) then raise exception 'Author scenario text changed';end if;
end $$;
notify pgrst,'reload schema';
